// Access input json safely
const inputJson = $input.item.json;

// Retrieve edited post, accounting for case sensitivity or nested properties
const rawPostText = 
  inputJson.EditedPost || 
  inputJson.editedPost || 
  (inputJson.data && (inputJson.data.EditedPost || inputJson.data.editedPost)) || 
  "";

// Clean line breaks
const postText = rawPostText.trim();;

// Grab asset URN from the upstream node
const assetUrn = $('LinkedIn Register Upload').first().json.value.asset;

// Build LinkedIn payload
const body = {
  author: "urn:li:person:YOUR_PERSON_ID",
  lifecycleState: "PUBLISHED",
  specificContent: {
    "com.linkedin.ugc.ShareContent": {
      shareCommentary: { text: postText },
      shareMediaCategory: "IMAGE",
      media: [
        {
          status: "READY",
          media: assetUrn
        }
      ]
    }
  },
  visibility: {
    "com.linkedin.ugc.MemberNetworkVisibility": "PUBLIC"
  }
};

return [{ json: { body: JSON.stringify(body) } }];
